const fs = require("fs");
const path = require("path");

const root = process.cwd();
const envExamplePath = path.join(root, "env.development.example");
const envDevelopmentPath = path.join(root, ".env.development");
const envWorktreePath = path.join(root, ".env.worktree");

function hashString(input) {
	let hash = 0;
	for (const character of input) {
		hash = (hash * 31 + character.charCodeAt(0)) % 1000;
	}
	return hash;
}

function createWorktreeEnv() {
	const workspaceName = path.basename(root);
	const offset = hashString(root) % 200;
	const port = 9000 + offset;
	const content = [
		`# Generated by scripts/bootstrap-worktree-env.js for ${workspaceName}`,
		`PORT=${port}`,
		`OTEL_SERVICE_NAME=node-template-${workspaceName}`,
		"OTEL_ENABLED=false",
		"OTEL_EXPORTER_OTLP_ENDPOINT=http://127.0.0.1:4318",
		"LOKI_ENABLED=false",
		"LOKI_URL=http://127.0.0.1:3100",
		"PROMETHEUS_BASE_URL=http://127.0.0.1:9090",
		"TEMPO_BASE_URL=http://127.0.0.1:3200",
		"GRAFANA_BASE_URL=http://127.0.0.1:3001",
		"SMOKE_STARTUP_BUDGET_MS=2000",
		"",
	].join("\n");

	fs.writeFileSync(envWorktreePath, content);
}

if (!fs.existsSync(envDevelopmentPath) && fs.existsSync(envExamplePath)) {
	fs.copyFileSync(envExamplePath, envDevelopmentPath);
	console.log("Created .env.development from env.development.example");
}

if (!fs.existsSync(envWorktreePath)) {
	createWorktreeEnv();
	console.log("Created .env.worktree with deterministic worktree defaults");
}
